def upperBiTreeError (hp : p ≠ ∞) (d : DyadicIndex → DyadicIndex → 𝕜) :
    MixedNorm 𝕜 p →L[𝕜] MixedNorm 𝕜 p :=
  (∑' k, upperDiagonalErrorTerm (𝕜 := 𝕜) (p := p) hp d k) + (∑' k, upperCoordinateErrorTerm (𝕜 := 𝕜) (p := p) hp d k)

